import { StringColumn, ReferenceColumn, IntegerColumn, BooleanColumn, Table } from '../../db'

export const sys_ui_list_element = Table({
    name: 'sys_ui_list_element',
    schema: {
        list_id: ReferenceColumn({ referenceTable: 'sys_ui_list' }),
        element: StringColumn({ mandatory: true }),
        max_value: BooleanColumn({ default: false }),
        min_value: BooleanColumn({ default: false }),
        average_value: BooleanColumn({ default: false }),
        sum: BooleanColumn({ default: false }),
        position: IntegerColumn({}),
    },
})
